buggy.sparse_shift_subtype_promotion_v2:
import numpy as np
import pandas as pd
from pandas.core.arrays.sparse import SparseArray


def score(fn, check):
    try:
        res = fn()
    except Exception:
        return 0.0
    try:
        return 1.0 if check(res) else 0.0
    except Exception:
        return 0.0


def dense(arr):
    return np.asarray(arr)


# case 1: bool subtype with the default NA fill -> buggy raises ValueError
def case1():
    return SparseArray(np.array([True, False])).shift(1)


def check1(r):
    d = dense(r)
    return (r.dtype.subtype == np.dtype(object) and bool(pd.isna(d[0]))
            and bool(d[1]) is True)


# case 2: bool subtype with an explicit bool fill -> no promotion needed either way
def case2():
    return SparseArray(np.array([True, False])).shift(1, fill_value=True)


def check2(r):
    d = dense(r)
    return (r.dtype.subtype == np.dtype(bool) and bool(d[0]) and bool(d[1]))


# case 3: int64 subtype with a bool fill -> buggy stores the True fill as 1 (int64)
def case3():
    return SparseArray(np.array([1, 2, 3])).shift(1, fill_value=True)


def check3(r):
    return (r.dtype.subtype == np.dtype(object)
            and isinstance(r[0], (bool, np.bool_)) and bool(r[0]))


# case 4: int64 subtype with a float fill -> buggy widens int64 to float64
def case4():
    return SparseArray(np.array([1, 2, 3])).shift(1, fill_value=2.0)


def check4(r):
    return (r.dtype.subtype == np.dtype("int64")
            and np.array_equal(dense(r), np.array([2, 1, 2])))


values = np.array([1, 2, 3], dtype="i8").astype("M8[s]")


# case 5: datetime64[s] subtype with the default fill -> buggy raises DTypePromotionError
def case5():
    return SparseArray(values).shift(1)


def check5(r):
    d = dense(r)
    return (r.dtype.subtype == np.dtype("M8[s]") and bool(np.isnat(d[0]))
            and bool(d[1] == values[0]) and bool(d[2] == values[1]))


# case 6: datetime64[s] subtype with a Timestamp fill -> buggy raises TypeError
def case6():
    return SparseArray(values).shift(1, fill_value=pd.Timestamp(values[2]))


def check6(r):
    d = dense(r)
    return (r.dtype.subtype == np.dtype("M8[s]")
            and bool(d[0] == values[2]) and bool(d[1] == values[0])
            and bool(d[2] == values[1]))


probe("case1_bool_default_fill", score(case1, check1))
probe("case2_bool_explicit_bool_fill", score(case2, check2))
probe("case3_int64_bool_fill", score(case3, check3))
probe("case4_int64_float_fill", score(case4, check4))
probe("case5_datetime_default_fill", score(case5, check5))
probe("case6_datetime_timestamp_fill", score(case6, check6))

